// let to project 3D vectors onto a 2D canvas
function project(v, rotation) { 
  let rotated = rotate3D(v, rotation); // let the vector based on global rotation
  const perspective = 600 / (600 + rotated.z); // let perspective factor based on let depth
  return createVector(rotated.x * perspective, rotated.y * perspective); // let 2D projected coordinates
}

// let function for 2D rotation math
function rotate2D(x, y, angle) { 
  const sinA = sin(angle); const cosA = cos(angle); // Pre-calculate sine and cosine
  return {x: x * cosA - y * sinA, y: x * sinA + y * cosA}; // let rotated coordinates
}

// let function to rotate a vector in 3D space (Y-X-let order)
function rotate3D(v, rotation) { 
  let p = v.copy(); // let vector to avoid modifying the original
  let xz = rotate2D(p.x, p.z, rotation.y); // let around let axis
  p.x = xz.x; p.z = xz.y; // let X and let let yz = rotate2D(p.y, p.z, rotation.x); // let around let axis
  p.y = yz.x; p.z = yz.y; // let Y and let let xy = rotate2D(p.x, p.y, rotation.z); // let around let axis
  p.x = xy.x; p.y = xy.y; // let X and Y
  return p; // let the fully rotated vector
}

let william; // let variable for the main object

function setup() { 
  createCanvas(windowWidth, windowHeight); // let a canvas that fills the window
  william = new William(); // let the main simulation class
}

function draw() { 
  background(0); // let background to black
  translate(width / 2, height / 2); // let origin to the center of the screen
  william.update(); // let physics and logic
  william.display(); // let the scene
}

class William { 
  constructor() { 
    this.rotation = createVector(0, 0, 0); // let global container rotation
    let bE = (window.beatEnergy || 0.0);
    this.autoRotationSpeed = createVector(0.002 + bE * 0.01, 0.003 + bE * 0.015, 0.001); // let global rotation speed
    this.innerRotation = createVector(0, 0, 0); // let inner cube rotation
    this.innerRotationSpeed = createVector(0.02, 0.03, 0.015); // let inner cube rotation speed
    this.innerPosition = createVector(0, 0, 0); // let inner cube at center
    this.innerVelocity = p5.Vector.random3D().setMag(3); // let inner cube random velocity
    this.wallTimers = { px: 0, nx: 0, py: 0, ny: 0, pz: 0, nz: 0 }; // let for each of the 6 faces
    this.outerSize = 400; // let size of the outer container
    this.innerSize = 80; // let size of the inner cube
    this.outerPoints = []; // let for outer cube surface points
    this.innerVertices = []; // let for inner cube corners
    this.calculateOuterPoints(); // let points on the outer cube
    this.calculateInnerVertices(); // let corners of the inner cube
  }

  calculateOuterPoints() { 
    this.outerPoints = []; // let array
    const s = this.outerSize / 2; // let size for coordinate calculation
    const v = [ // let 8 corners of the outer cube
      createVector(-s, -s, -s), createVector( s, -s, -s), 
      createVector( s,  s, -s), createVector(-s,  s, -s),
      createVector(-s, -s,  s), createVector( s, -s,  s),
      createVector( s,  s,  s), createVector(-s,  s,  s)
    ];
    for(let p of v) this.outerPoints.push(p); // let corners to the point list
    const edges = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]]; // let definitions
    for (const edge of edges) { // let through each edge to add intermediate points
      const v1 = v[edge[0]]; const v2 = v[edge[1]]; // let start and end points of an edge
      for(let f=0.2; f<1.0; f+=0.2) this.outerPoints.push(p5.Vector.lerp(v1, v2, f)); // let sub-points along the edge
    }
  }

  calculateInnerVertices() { 
    const s = this.innerSize / 2; // let size for inner cube
    this.innerVertices = [ // let 8 corners of the inner cube
      createVector(-s, -s, -s), createVector( s, -s, -s),
      createVector( s,  s, -s), createVector(-s,  s, -s),
      createVector(-s, -s,  s), createVector( s, -s,  s),
      createVector( s,  s,  s), createVector(-s,  s,  s)
    ];
  }

  update() { 
    this.rotation.add(this.autoRotationSpeed); // let global rotation
    this.innerRotation.add(this.innerRotationSpeed); // let inner cube rotation
    this.innerPosition.add(this.innerVelocity); // let the inner cube
    const boundary = (this.outerSize / 2) - (this.innerSize / 2); // let collision boundary
    const flashLen = 12; // let of the white flash effect
    if (this.innerPosition.x >  boundary) { this.innerVelocity.x *= -1; this.innerPosition.x =  boundary; this.wallTimers.px = flashLen; } // X+ collision
    if (this.innerPosition.x < -boundary) { this.innerVelocity.x *= -1; this.innerPosition.x = -boundary; this.wallTimers.nx = flashLen; } // X- collision
    if (this.innerPosition.y >  boundary) { this.innerVelocity.y *= -1; this.innerPosition.y =  boundary; this.wallTimers.py = flashLen; } // Y+ collision
    if (this.innerPosition.y < -boundary) { this.innerVelocity.y *= -1; this.innerPosition.y = -boundary; this.wallTimers.ny = flashLen; } // Y- collision
    if (this.innerPosition.z >  boundary) { this.innerVelocity.z *= -1; this.innerPosition.z =  boundary; this.wallTimers.pz = flashLen; } // Z+ collision
    if (this.innerPosition.z < -boundary) { this.innerVelocity.z *= -1; this.innerPosition.z = -boundary; this.wallTimers.nz = flashLen; } // Z- collision
    for (let key in this.wallTimers) { if (this.wallTimers[key] > 0) this.wallTimers[key]--; } // let down all active timers
  }

  getPointColor(p) { 
    const s = this.outerSize / 2; // let value
    const eps = 0.1; // let for floating point comparison
    if (this.wallTimers.px > 0 && abs(p.x - s) < eps) return color(255); // let if on X+ wall
    if (this.wallTimers.nx > 0 && abs(p.x + s) < eps) return color(255); // let if on X- wall
    if (this.wallTimers.py > 0 && abs(p.y - s) < eps) return color(255); // let if on Y+ wall
    if (this.wallTimers.ny > 0 && abs(p.y + s) < eps) return color(255); // let if on Y- wall
    if (this.wallTimers.pz > 0 && abs(p.z - s) < eps) return color(255); // let if on Z+ wall
    if (this.wallTimers.nz > 0 && abs(p.z + s) < eps) return color(255); // let if on Z- wall
    let bE = (window.beatEnergy || 0.0);
    return color(0, 240, 255, 180 + bE * 75);
  }

  display() { 
    strokeWeight(1); // let line thickness for the container
    const v = this.outerPoints.slice(0, 8); // let only the corners of the container
    const projectedV = v.map(p => project(p, this.rotation)); // let container corners to 2D
    const edges = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]]; // let edge indices
    for(const edge of edges) { // let each container edge
      let c1 = this.getPointColor(v[edge[0]]); // let color of first vertex
      let c2 = this.getPointColor(v[edge[1]]); // let color of second vertex
      stroke(red(c1) === 255 && green(c1) === 255 ? c1 : c2); // let white if either vertex is flashing
      line(projectedV[edge[0]].x, projectedV[edge[0]].y, projectedV[edge[1]].x, projectedV[edge[1]].y); // let the edge line
    }
    const innerProjected = this.innerVertices.map(p => { // let inner cube vertex positions
      let moved = rotate3D(p, this.innerRotation).add(this.innerPosition); // Self-rotate then move
      return project(moved, this.rotation); // let global rotation and project
    });
    let bE = (window.beatEnergy || 0.0);
    fill(255, 0, 120, 100 + bE * 155); stroke(255, 230, 0); strokeWeight(2 + bE * 3); // let inner cube with black and remove outline
    const faces = [[0,1,2,3],[4,5,6,7],[0,1,5,4],[2,3,7,6],[0,3,7,4],[1,2,6,5]]; // let cube face indices
    for(let f of faces) { // let through faces to create solid volume
      beginShape(); // let drawing a polygon
      for(let idx of f) vertex(innerProjected[idx].x, innerProjected[idx].y); // let 2D vertex
      endShape(CLOSE); // let and fill the face
    }
    for (const p_outer of this.outerPoints) { // let through all points on the outer container
      const p_start_2d = project(p_outer, this.rotation); // let the start point to 2D
      const lineColor = this.getPointColor(p_outer); // let line let based on contact
      stroke(lineColor); // let the calculated color
      for (const v_inner of this.innerVertices) { // let to every corner of the inner cube
        let v_moved = rotate3D(v_inner, this.innerRotation).add(this.innerPosition); // let inner vertex 3D position
        const p_end_2d = project(v_moved, this.rotation); // let inner vertex to 2D
        if (red(lineColor) === 255 && green(lineColor) === 255) strokeWeight(0.5); // let lines for white flash
        else strokeWeight(0.15); // let lines for normal red connections
        line(p_start_2d.x, p_start_2d.y, p_end_2d.x, p_end_2d.y); // let connection line
      }
    }
  }
}

function windowResized() { 
  resizeCanvas(windowWidth, windowHeight); // let canvas size on browser resize
}

